(window.TIMELINE_TRANSLATIONS=window.TIMELINE_TRANSLATIONS||{})["isv"]={"qin-dynasty":{"id":"qin-dynasty","title":"Dinastija Cin","summary":"Država Cin pobědila svoje glavne suparniky pod vladoju Jing Čenga, ktory prijel imperatorsky titul Cin Ši Huang. Dinastija trvala samo kratko, ale jej vojenne i administrativne praktiky vplyvali na slědujučo imperiju Han.","began":"Zavojevanja Cin skončili se zjedinjenjem, i Jing Čeng se proglasil imperatorom.","ended":"Dinastija se razpala v lětah po smrti Cin Ši Huanga; suparničeče sily se borili, nim Han ustanovil imperatorsku vladu.","why":"Stvorila imperatorsku političnu strukturu, ktoru pozdnějše dinastije prilagodili."},"confucius":{"id":"confucius","title":"Konfucij uči etičnu vladu","summary":"Konfucij učil v periodu Vesen i Jeseni. Podčrkival moralno ponašanje, rodinne odgovornosti, učenje i dolžnost vladara vladati črez krěposť. Njegovo učenje stalo važnoju intelektualnoju tradicijeju, i pozdnějše imperatorske vlady postavili konfucijanske teksty v centr oficialnogo obrazovanja.","why":"Njegovo učenje oblikovalo političnu etiku, obrazovanje i rodinne idealy po vsej Vozhodnoj Aziji."},"stonewall-riots":{"id":"stonewall-riots","title":"Vozstanje Stonewall","summary":"Klienti i podporniki sprotivili se policijnomu napadu v Stonewall Inn v Novom Jorku, po čem slědovali dalšne sudary i demonstracije. Vozstanje stalo močnoju točkoju odniesenja za rastuče dviženje protiv progonjenja seksualnyh menšin.","why":"Stonewall pomogl oživiti gejsko osvobodženje i pozdnějšu LGBTQ organizaciju, ale ne byl prvym aktom sprotivjenja."}};
